    fs::remove_all(data_directory, error);
    if (error)
        std::cerr << "HARNESS WARNING data dir not fully removed: " << error.message() << " ("
                  << data_directory.string() << ")\n";
    if (state->result < 0)
        return gui_result == 0 ? 1 : gui_result;
    return state->result;
}

